{
  "vulnerable_symbols": [],
  "trigger": "当 Flask 应用在缓存代理后启用永久 session 且请求中不访问/修改 session 时，默认刷新 session 的响应缺少 Vary: Cookie，导致代理缓存并可能转发其他用户的 session cookie。",
  "preconditions": [
    "应用位于不剥离 Cookie 或不忽略带 Cookie 响应的缓存代理之后",
    "代理会缓存 Set-Cookie 头",
    "应用设置 session.permanent = True",
    "请求处理过程中不访问或修改 session",
    "SESSION_REFRESH_EACH_REQUEST 启用（默认）",
    "应用未设置 Cache-Control: private/no-store 等禁止缓存头"
  ],
  "exploit_evidence": [
    {
      "src": 3,
      "kind": "poc",
      "quote": "EIP currently links 1 repository PoC and 1 lab environment to CVE-2023-30861."
    },
    {
      "src": 5,
      "kind": "poc",
      "quote": "本项目是用于复现Flask的CVE-2023-30861漏洞的PoC。"
    }
  ],
  "fixed_version": "2.2.5, 2.3.2",
  "summary_zh": "Flask 刷新永久会话缺少 Vary: Cookie，缓存代理可能泄露用户 session cookie。"
}
